CREATE TABLE planning_maintenance (workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('frozen','purging')), PRIMARY KEY(workspace_id,project_id));
ALTER TABLE planning_history ADD COLUMN project_id TEXT;
UPDATE planning_history SET project_id=(SELECT project_id FROM planning_sprints WHERE planning_sprints.workspace_id=planning_history.workspace_id AND planning_sprints.id=planning_history.sprint_id);
ALTER TABLE planning_receipts ADD COLUMN project_id TEXT;
UPDATE planning_receipts SET project_id=(SELECT project_id FROM planning_sprints WHERE planning_sprints.workspace_id=planning_receipts.workspace_id AND planning_sprints.id=planning_receipts.result_id);
ALTER TABLE planning_events ADD COLUMN project_id TEXT;
UPDATE planning_events SET project_id=(SELECT project_id FROM planning_sprints WHERE planning_sprints.workspace_id=planning_events.workspace_id AND planning_sprints.id=planning_events.aggregate_id);
CREATE INDEX planning_history_project ON planning_history(workspace_id,project_id);
CREATE INDEX planning_receipts_project ON planning_receipts(workspace_id,project_id);
CREATE INDEX planning_events_project ON planning_events(workspace_id,project_id);
CREATE TRIGGER planning_sprints_freeze_insert BEFORE INSERT ON planning_sprints WHEN (EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=NEW.workspace_id AND project_id='') OR EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=NEW.workspace_id AND project_id=NEW.project_id)) OR (EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=NEW.workspace_id AND project_id<>'' AND NEW.project_id IS NULL)) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER planning_sprints_freeze_update BEFORE UPDATE ON planning_sprints WHEN ((EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=NEW.workspace_id AND project_id='') OR EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=NEW.workspace_id AND project_id=NEW.project_id)) OR (EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=OLD.workspace_id AND project_id='') OR EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=OLD.workspace_id AND project_id=OLD.project_id))) OR (EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=NEW.workspace_id AND project_id<>'' AND NEW.project_id IS NULL) OR EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=OLD.workspace_id AND project_id<>'' AND OLD.project_id IS NULL)) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER planning_items_freeze_insert BEFORE INSERT ON planning_items WHEN EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=NEW.workspace_id AND project_id='') OR EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=NEW.workspace_id AND project_id=(SELECT project_id FROM planning_sprints WHERE workspace_id=NEW.workspace_id AND id=NEW.sprint_id)) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER planning_items_freeze_update BEFORE UPDATE ON planning_items WHEN (EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=NEW.workspace_id AND project_id='') OR EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=NEW.workspace_id AND project_id=(SELECT project_id FROM planning_sprints WHERE workspace_id=NEW.workspace_id AND id=NEW.sprint_id))) OR (EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=OLD.workspace_id AND project_id='') OR EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=OLD.workspace_id AND project_id=(SELECT project_id FROM planning_sprints WHERE workspace_id=OLD.workspace_id AND id=OLD.sprint_id))) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
