CREATE TRIGGER planning_guards_freeze_insert BEFORE INSERT ON planning_guards WHEN EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=NEW.workspace_id AND project_id='') BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER planning_guards_freeze_update BEFORE UPDATE ON planning_guards WHEN (EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=NEW.workspace_id AND project_id='')) OR (EXISTS(SELECT 1 FROM planning_maintenance WHERE workspace_id=OLD.workspace_id AND project_id='')) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
